select case when rating >= 3.9 then 'high' when rating >= 1.5 then 'mid' else 'low' end as rating_bucket, round((100 * sum(case when city = 'New York' then 1 else 0 end)) / count(*), 1) as pct_new_york, round((100 * sum(case when country = 'JP' then 1 else 0 end)) / count(*), 1) as pct_jp from suppliers group by case when rating >= 3.9 then 'high' when rating >= 1.5 then 'mid' else 'low' end;
